fn parse_age(s: &str) -> Result<u8, String> {
    match s.trim().parse::<u8>() {
        Ok(n) if n <= 130 => Ok(n),
        Ok(_) => Err("âge irréaliste".into()),
        Err(e) => Err(format!("pas un nombre : {e}")),
    }
}

fn lire_config(chemin: &str)
    -> Result<Config, Box<dyn Error>> {
    let texte = fs::read_to_string(chemin)?;
    let config = toml::from_str(&texte)?;
    Ok(config)
}

