use std::num::ParseIntError;

fn somme(a: &str, b: &str) -> Result<i32, ParseIntError> {
    Ok(a.parse::<i32>()? + b.parse::<i32>()?)
}

println!("{:?}", somme("2", "3"));
println!("{}", somme("2", "x").is_err());

