fn diviser(a: i32, b: i32) -> Option<i32> {
    if b == 0 { None } else { Some(a / b) }
}

fn calcul() -> Option<i32> {
    let x = diviser(20, 2)?;
    let y = diviser(x, 0)?;
    Some(y + 1)
}

println!("{:?}", calcul());
